public struct SdkWireNode {
    public var nodeId: UInt32
    public var parentId: UInt32
    /**
     * `"screen" | "container" | "button" | "masked_input" | "text" | "image_placeholder" | "error_banner"`
     */
    public var kind: String
    public var x: UInt16
    public var y: UInt16
    public var w: UInt16
    public var h: UInt16
    public var bgRgba: UInt32
    public var label: String
    /**
     * Default-deny privacy (`P3-01`): unless `unmasked == true` (and `kind != "masked_input"`),
     * any non-empty `label` is replaced on client with fixed-length `"████"`.
     */
    public var unmasked: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(nodeId: UInt32, parentId: UInt32, 
        /**
         * `"screen" | "container" | "button" | "masked_input" | "text" | "image_placeholder" | "error_banner"`
         */kind: String, x: UInt16, y: UInt16, w: UInt16, h: UInt16, bgRgba: UInt32, label: String, 
        /**
         * Default-deny privacy (`P3-01`): unless `unmasked == true` (and `kind != "masked_input"`),
         * any non-empty `label` is replaced on client with fixed-length `"████"`.
         */unmasked: Bool = false) {
        self.nodeId = nodeId
        self.parentId = parentId
        self.kind = kind
        self.x = x
        self.y = y
        self.w = w
        self.h = h
        self.bgRgba = bgRgba
        self.label = label
        self.unmasked = unmasked
    }
}



extension SdkWireNode: Equatable, Hashable {
    public static func ==(lhs: SdkWireNode, rhs: SdkWireNode) -> Bool {
        if lhs.nodeId != rhs.nodeId {
            return false
        }
        if lhs.parentId != rhs.parentId {
            return false
        }
        if lhs.kind != rhs.kind {
            return false
        }
        if lhs.x != rhs.x {
            return false
        }
        if lhs.y != rhs.y {
            return false
        }
        if lhs.w != rhs.w {
            return false
        }
        if lhs.h != rhs.h {
            return false
        }
        if lhs.bgRgba != rhs.bgRgba {
            return false
        }
        if lhs.label != rhs.label {
            return false
        }
        if lhs.unmasked != rhs.unmasked {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(nodeId)
        hasher.combine(parentId)
        hasher.combine(kind)
        hasher.combine(x)
        hasher.combine(y)
        hasher.combine(w)
        hasher.combine(h)
        hasher.combine(bgRgba)
        hasher.combine(label)
        hasher.combine(unmasked)
    }
}


